                $user->azguardDefaultPanel();
                $registry->currentPanel();
                // $registry->forModel() in a comment
                $name = 'azguardDefaultPanel';
            }
        }
        PHP;

    expect(panelSelectionUses($code))->toBe(['CurrentPanel', 'defaultFor', 'forModel', 'azguardDefaultPanel']);
});

